        int dx = points[other][0] - x, dy = points[other][1] - y;
        if (dx == 0 && dy == 0) {
          ++duplicates;
          continue;
        }
        int divisor = gcd(dx < 0 ? -dx : dx, dy < 0 ? -dy : dy);
        dx /= divisor;
        dy /= divisor;
        if (dx < 0 || (dx == 0 && dy < 0)) {
          dx = -dx;
          dy = -dy;
        }
        ++groups[(dy + 2000) * 4001 + dx];
