                first ^= value;
            else
                second ^= value;
        }
        foreach (int value in values)
        {
            if ((value & bit) != 0)
                first ^= value;
            else
                second ^= value;
        }
        return [Math.Min(first, second), Math.Max(first, second)];
    }
}

